package rpc

import (
	"encoding/hex"
	"testing"

	jsonrpc "github.com/cometbft/cometbft/rpc/jsonrpc/client"
	"github.com/scalarorg/xchains-indexer/config"
	"github.com/stretchr/testify/require"
)

const (
	BLOCK1 string = ""
	BLOCK2 string = ""
)

func TestParseBlockResult(t *testing.T) {
	block_data, err := hex.DecodeString(BLOCK2)
	require.NoError(t, err)
	result3704 := new(ResultBlockResults)
	_, err = unmarshalResponseBytes(block_data, jsonrpc.URIClientRequestID, result3704)
	require.NoError(t, err)
	println("===== Version 3704 =====")
	config.Log.Debugf("result3704: %++v", result3704)
	println("===== Version 3704 =====")
}
